.section { padding: 96px 0; }
.section--alt { background: var(--bg-elev); border-block: 1px solid rgba(28, 42, 43, 0.6); }
.section__head { max-width: 760px; margin: 0 auto 48px; text-align: center; }
.eyebrow {
