  display: grid; place-items: center; width: 44px; height: 44px; margin-bottom: 20px;
  border-radius: 12px; border: 1px solid rgba(53, 240, 168, 0.25); background: var(--aurora-soft);
}
.card__ico svg { width: 24px; height: 24px; fill: none; stroke: var(--aurora); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }

